update public.learning_paths
set
  title = 'Principles of Management',
  goal = 'Principles of Management',
  summary = 'This syllabus is designed for a one-semester introductory management course for business majors and management-adjacent students. It builds practical fluency in managerial thinking, organizational design, people leadership, ethical judgment, and change execution.',
  data = $pomjson${"slug": "principles-of-management", "title": "Principles of Management", "description": "This syllabus is designed for a one-semester introductory management course for business majors and management-adjacent students. It builds practical fluency in managerial thinking, organizational design, people leadership, ethical judgment, and change execution.", "topics": [{"id": "a39449c4-36cf-47f2-9a27-fd0593c9188e", "type": "topic", "title": "Course Orientation, Managerial Roles, and the Management Process", "description": "This opening unit defines what managers do and why management matters in every kind of organization. Students learn the classic management functions and the realities of managerial work.", "children": [{"id": "98e3ed6d-5623-4a8e-ac70-51e6e56b50fb", "type": "subtopic", "title": "Managerial Work and Organizational Purpose", "children": [{"id": "1fe7e379-ac8f-453f-8510-43739e933af7", "type": "concept", "title": "Organizations as goal-directed systems"}, {"id": "0d88406a-f142-4215-ab45-57a0e314eacb", "type": "concept", "title": "Efficiency and effectiveness"}, {"id": "ef3ca580-6239-4116-a855-37b4607068fc", "type": "concept", "title": "Value creation for stakeholders"}], "description": "Students learn that management is about achieving goals through people, systems, and resources."}, {"id": "0889d91d-bf08-4f86-82d3-d2d78deab75b", "type": "subtopic", "title": "Management Functions", "children": [{"id": "7da985c2-f606-4833-8282-7c1c03fc067c", "type": "concept", "title": "Planning"}, {"id": "bc12f5df-0476-49a8-97ed-362e30730818", "type": "concept", "title": "Organizing"}, {"id": "42761974-ecf4-4e6b-897b-d2193706391f", "type": "concept", "title": "Leading"}, {"id": "19c3ae88-c4f3-4550-b8da-0124104ffe67", "type": "concept", "title": "Controlling"}], "description": "The classic functions give students a map for the rest of the course."}, {"id": "d9a7a214-57bc-4fed-b212-684fb287a2f9", "type": "subtopic", "title": "Managerial Roles and Skills", "children": [{"id": "c63aceea-f7fc-4488-ad8c-128e2261d262", "type": "concept", "title": "Mintzberg's managerial roles"}, {"id": "ad0f28fb-3b67-49da-9f43-8bc8d109e1ad", "type": "concept", "title": "Technical, human, and conceptual skills"}, {"id": "30d66eeb-dc22-4569-a32d-66477763b639", "type": "concept", "title": "First-line, middle, and top managers"}], "description": "Students learn how managers operate across interpersonal, informational, and decision roles."}]}, {"id": "22e70406-1e86-4cb5-a647-021420c96027", "type": "topic", "title": "Evolution of Management Thought and Contemporary Management Context", "description": "This unit shows how management ideas developed and why different theories still matter. Students learn to use management history as a toolkit rather than a museum.", "children": [{"id": "15b6d90f-62d5-4fae-9b01-600aeea38322", "type": "subtopic", "title": "Classical Management Foundations", "children": [{"id": "207bc79a-81ed-483f-8d7c-9fe91ce34071", "type": "concept", "title": "Scientific management"}, {"id": "6d32e490-61ca-4b83-be0a-a912b593cf91", "type": "concept", "title": "Administrative principles"}, {"id": "e770afda-3167-4362-a495-052bb170aece", "type": "concept", "title": "Bureaucratic organization"}], "description": "Students learn how early management focused on efficiency, structure, and formal authority."}, {"id": "4b8908b2-9465-4c1b-b187-61a172ae42a2", "type": "subtopic", "title": "Human Relations and Behavioral Views", "children": [{"id": "aa400fe4-97c3-407b-ac65-c985b852e179", "type": "concept", "title": "Hawthorne studies"}, {"id": "408868ca-1c53-49de-b034-fdec8a2d381d", "type": "concept", "title": "Human relations movement"}, {"id": "34392f48-87a5-44f4-8fcf-e9bbe3433c8a", "type": "concept", "title": "Behavioral science contributions"}], "description": "Students see why motivation, social needs, and informal groups matter."}, {"id": "750c3be7-191c-4c0d-b957-e5de4c14e9ec", "type": "subtopic", "title": "Contemporary Context", "children": [{"id": "6608cbc8-cb91-4309-8c71-bd7812544e88", "type": "concept", "title": "Systems thinking"}, {"id": "ca650ac8-24f0-4262-ae3c-45b8071339ab", "type": "concept", "title": "Contingency approach"}, {"id": "910f5893-6ad7-4e12-ab45-fceeb5e7c986", "type": "concept", "title": "Digital, remote, and hybrid work"}], "description": "Students connect management to today's technology, uncertainty, and stakeholder expectations."}]}, {"id": "fc07f5f1-82c9-4446-8288-4f34ea58f4ac", "type": "topic", "title": "Planning, Goal Setting, and Strategic Decision-Making", "description": "Planning gives managers direction before action. This unit teaches how goals, strategies, and decisions align resources with priorities.", "children": [{"id": "69cae2f8-02b0-44a9-9f0f-e5afa653bae0", "type": "subtopic", "title": "Planning Levels and Goal Setting", "children": [{"id": "81d03ed9-cf36-42b0-8cce-bdaff017eee0", "type": "concept", "title": "Mission, vision, goals, and objectives"}, {"id": "c8fcfe3b-3941-4d6e-91df-d679dba07534", "type": "concept", "title": "SMART goals and OKRs"}, {"id": "1fe566b6-c00a-4747-9411-0a4b95cb50cc", "type": "concept", "title": "Single-use and standing plans"}], "description": "Students learn to distinguish strategic, tactical, and operational plans."}, {"id": "cfc0b2e1-c34e-42b1-a966-9729ad40cf10", "type": "subtopic", "title": "Strategic Thinking Basics", "children": [{"id": "b06c566e-9d27-4658-8f0c-b8ed2563e998", "type": "concept", "title": "SWOT analysis"}, {"id": "f11160b9-4e1f-4833-b79f-c4c5bc369de3", "type": "concept", "title": "Competitive advantage"}, {"id": "551ddb08-cc0d-4260-a5aa-2e1cdcd9a0cd", "type": "concept", "title": "Scenario thinking"}], "description": "Students learn the foundation for later strategy and competitive analysis."}, {"id": "a9f67e24-2e15-45b0-8fb5-991439722acf", "type": "subtopic", "title": "Decision-Making Process", "children": [{"id": "4b12bbe3-be45-4f24-be1b-8bbb7e7615d6", "type": "concept", "title": "Problem definition"}, {"id": "98f64d94-060f-495d-8781-3081afa9e03d", "type": "concept", "title": "Alternatives and criteria"}, {"id": "9726dd54-d151-48be-a570-25a99b62dfd6", "type": "concept", "title": "Implementation and evaluation"}], "description": "Students learn a disciplined approach to managerial choices."}]}, {"id": "b771381e-8ebf-44b4-a015-9545c4e5918b", "type": "topic", "title": "Problem Solving, Managerial Decision Biases, and Evidence-Based Management", "description": "Managers often decide with incomplete information. This unit helps students recognize bias, use evidence, and improve judgment.", "children": [{"id": "0fda923d-30c8-4028-94d4-727c386b4231", "type": "subtopic", "title": "Types of Managerial Problems", "children": [{"id": "9ae31771-8d51-47ca-bde0-850da959919f", "type": "concept", "title": "Programmed and nonprogrammed decisions"}, {"id": "4f756410-3ce2-4c59-89cb-7e54301edd08", "type": "concept", "title": "Certainty, risk, and uncertainty"}, {"id": "13dd2f7f-afda-493d-90da-9f324fd36cad", "type": "concept", "title": "Structured versus ambiguous problems"}], "description": "Students learn that different problems require different decision approaches."}, {"id": "48e4babe-4c86-4699-8e28-81e13f0875f6", "type": "subtopic", "title": "Decision Biases", "children": [{"id": "113f2724-bf27-40b5-a70d-abdffe228aa9", "type": "concept", "title": "Confirmation bias"}, {"id": "973301bf-0850-459d-94fb-5c620e803bbf", "type": "concept", "title": "Anchoring and availability"}, {"id": "95568df3-8815-465f-8e53-45dddb6c050b", "type": "concept", "title": "Escalation of commitment"}], "description": "Students learn common traps that distort managerial judgment."}, {"id": "ec236fab-dd70-4e3d-b402-bbc5ed1b8262", "type": "subtopic", "title": "Evidence-Based Management", "children": [{"id": "8545de01-830a-4e65-b04f-147e9ffaabff", "type": "concept", "title": "Using data and research"}, {"id": "e4446674-8d7c-42aa-b3f6-693aeeda8610", "type": "concept", "title": "Testing assumptions"}, {"id": "979aa2af-d1e6-4c6f-bde5-475ccfafe17c", "type": "concept", "title": "Learning from results"}], "description": "Students learn to combine data, expertise, stakeholder values, and context."}]}, {"id": "4ee5adbb-6f3f-4a17-9810-edb77652b7cc", "type": "topic", "title": "Organizational Design, Structure, and Coordination", "description": "Organizing determines how work is divided and coordinated. This unit teaches the structures managers use to support strategy and execution.", "children": [{"id": "5715ca12-8e90-45d9-a571-a884b3e73f2c", "type": "subtopic", "title": "Division of Work and Authority", "children": [{"id": "28c5a673-888f-4b43-9b22-0c6e60e98d19", "type": "concept", "title": "Specialization"}, {"id": "33058d5c-477e-442e-a003-266f1e065303", "type": "concept", "title": "Chain of command"}, {"id": "729ea301-92b3-4e7e-acaa-a88d357a1737", "type": "concept", "title": "Span of control and delegation"}], "description": "Students learn how organizations assign responsibility and decision rights."}, {"id": "592d1ed8-0b08-44c0-8e75-c540585b02bf", "type": "subtopic", "title": "Structure Types", "children": [{"id": "890168a8-8cf5-4833-9b99-daed14af69a1", "type": "concept", "title": "Functional, divisional, matrix, team-based, network structures"}, {"id": "f712ef52-64c6-40d3-9314-377401abf972", "type": "concept", "title": "Centralization versus decentralization"}, {"id": "633271bd-ddb4-4388-a82e-6f4ce9623f4b", "type": "concept", "title": "Mechanistic versus organic design"}], "description": "Students compare common structures and their tradeoffs."}, {"id": "3fc91901-4023-44d0-a955-3b70664548b3", "type": "subtopic", "title": "Coordination and Control Systems", "children": [{"id": "758426c4-85be-45c9-b13a-5c9372c1d739", "type": "concept", "title": "Standardization and mutual adjustment"}, {"id": "0741d099-702a-4940-b222-1ba867a0f880", "type": "concept", "title": "Cross-functional coordination"}, {"id": "efeb38e6-493e-48c1-9e80-b269e64d6ebf", "type": "concept", "title": "Formal and informal systems"}], "description": "Students learn how work is integrated across roles and units."}]}, {"id": "dc81d2af-adff-42dc-9d93-adb24791b7f6", "type": "topic", "title": "Staffing, Human Resource Management, and Talent Systems", "description": "People systems shape organizational capability. This unit introduces the manager's role in hiring, developing, evaluating, and retaining employees.", "children": [{"id": "ef512c15-9502-4752-a569-4c02adac22a8", "type": "subtopic", "title": "Workforce Planning and Staffing", "children": [{"id": "bc8445a6-ccaa-4378-943b-25f947718e12", "type": "concept", "title": "Job analysis and job design"}, {"id": "9b8ff366-2b13-4260-a323-eaa975bd8e93", "type": "concept", "title": "Recruiting and selection"}, {"id": "3d86f8fd-b5e3-4a83-8d39-6b3964e6e016", "type": "concept", "title": "Legal and ethical hiring considerations"}], "description": "Students learn how managers align talent with organizational needs."}, {"id": "0b430a48-6cce-4bc6-96e1-3145e90fce5c", "type": "subtopic", "title": "Development and Performance Management", "children": [{"id": "5214b138-0598-400a-8695-c5ad3bf4db90", "type": "concept", "title": "Training and development"}, {"id": "e5ca05b3-86b6-4a76-9e01-75313d568689", "type": "concept", "title": "Feedback and appraisal"}, {"id": "8ed583b8-503e-4ae4-abf6-d510d745f667", "type": "concept", "title": "Coaching and career development"}], "description": "Students learn how employees grow and how performance is evaluated."}, {"id": "52af801d-6b22-48a9-8e24-e125f8a9f1e2", "type": "subtopic", "title": "Rewards and Retention", "children": [{"id": "3dd2109f-b7ea-45a2-bf36-bb2859417825", "type": "concept", "title": "Pay and benefits"}, {"id": "b3dcf270-c560-4fbd-a343-ffdb955722db", "type": "concept", "title": "Recognition systems"}, {"id": "262859d3-97bf-447a-973a-90a4d62048e1", "type": "concept", "title": "Retention, engagement, and turnover"}], "description": "Students connect compensation and recognition to motivation and fairness."}]}, {"id": "1c04f1bb-729c-4102-9a05-5c55c9b8a143", "type": "topic", "title": "Leadership Theories, Styles, and Managerial Influence", "description": "Leadership is the process of influencing people toward shared goals. This unit surveys major leadership perspectives and practical influence skills.", "children": [{"id": "559f5c2d-2a36-4c41-92d1-f783c237fc15", "type": "subtopic", "title": "Leadership Theories", "children": [{"id": "9f23d236-8eb7-44b6-b537-0b5623d45c55", "type": "concept", "title": "Trait and behavioral approaches"}, {"id": "53d03e42-515a-4cd3-86eb-04ae2b5a7fc7", "type": "concept", "title": "Contingency and situational leadership"}, {"id": "28770fbc-374c-424c-b780-1fd30c8f8602", "type": "concept", "title": "Transformational and servant leadership"}], "description": "Students learn how leadership thinking has evolved."}, {"id": "a7252df7-d78c-46c3-9dd3-5cfbfe20a9e0", "type": "subtopic", "title": "Leadership Styles and Practices", "children": [{"id": "fe73e097-f300-41a4-90ef-4b858cc81750", "type": "concept", "title": "Directive, participative, coaching, and delegating styles"}, {"id": "3099ca23-2d42-49e4-89ce-c6c1770f72ea", "type": "concept", "title": "Emotional intelligence"}, {"id": "84446dd3-f4cc-472b-8e60-50e590536919", "type": "concept", "title": "Leader-member exchange overview"}], "description": "Students connect style to context, people, and outcomes."}, {"id": "86314adc-3616-404e-82f1-f2f8089190a8", "type": "subtopic", "title": "Influence Without Authority", "children": [{"id": "8ff0abde-30f7-4cb0-9aeb-769ba4033df9", "type": "concept", "title": "Persuasion and credibility"}, {"id": "a5cf8c93-b7a3-44cc-bf6c-d35672ee174b", "type": "concept", "title": "Coalition building"}, {"id": "a28b4d3a-b70c-4df8-998a-e7dae16f4b00", "type": "concept", "title": "Stakeholder mapping"}], "description": "Students learn that managers often lead peers, partners, and stakeholders without formal power."}]}, {"id": "010853e8-fd11-49e7-83a2-bafd189f0200", "type": "topic", "title": "Motivation, Job Design, and Employee Engagement", "description": "Motivation explains why people choose effort, persistence, and direction at work. Students learn major theories and how managers shape meaningful work.", "children": [{"id": "8b630652-283d-41c2-95fd-1974163f1c7d", "type": "subtopic", "title": "Classic Motivation Theories", "children": [{"id": "bdd2cc5e-7d82-4f42-ad64-097aef55c6e2", "type": "concept", "title": "Maslow's hierarchy"}, {"id": "61ea0815-9c11-45cf-a3a8-6e558bc74b6e", "type": "concept", "title": "Herzberg's two-factor theory"}, {"id": "68a5f5ac-2a32-42a0-93cc-e8ced8aa0d09", "type": "concept", "title": "McClelland's acquired needs"}], "description": "Students learn enduring frameworks for understanding human needs and incentives."}, {"id": "d5344e51-57cc-4cbe-946c-f16baf15cede", "type": "subtopic", "title": "Process Theories", "children": [{"id": "9c3c6caa-e677-4583-8111-bfd65eb38c97", "type": "concept", "title": "Expectancy theory"}, {"id": "468d242e-e973-48df-8e22-3dab5b42834a", "type": "concept", "title": "Equity theory"}, {"id": "fbe85604-2b50-4d11-ba1a-bbb06cf9b294", "type": "concept", "title": "Goal-setting theory"}], "description": "Students learn how perceptions of fairness, expectancy, and goals shape behavior."}, {"id": "821c451e-4013-4e05-9eb6-fab5b1a5ac35", "type": "subtopic", "title": "Job Design and Engagement", "children": [{"id": "7e5a5f3e-46d0-494a-b9e9-cb663df9872a", "type": "concept", "title": "Job characteristics model"}, {"id": "88c1b009-f2b1-4205-a58d-ca562c6ef9d2", "type": "concept", "title": "Autonomy, mastery, and purpose"}, {"id": "bfb3220f-ece8-4ed6-93ff-98594f7c9512", "type": "concept", "title": "Engagement drivers and burnout risks"}], "description": "Students learn how work itself can create or drain motivation."}]}, {"id": "d699f41e-50e2-40f4-ae6f-df69bd4d2eba", "type": "topic", "title": "Groups, Teams, Communication, and Conflict Management", "description": "Managers accomplish much of their work through groups and communication. This unit teaches how to build effective teams, communicate clearly, and handle conflict productively.", "children": [{"id": "70798f36-6b65-457a-92a3-0af601059063", "type": "subtopic", "title": "Group and Team Dynamics", "children": [{"id": "3884d33d-52d1-4475-9fc0-42d8be785f8d", "type": "concept", "title": "Stages of team development"}, {"id": "d421ab47-fc63-475b-b158-9ceb97790101", "type": "concept", "title": "Roles, norms, and cohesion"}, {"id": "6de8c273-f917-49b6-8c30-e487f5ace1c8", "type": "concept", "title": "Psychological safety"}], "description": "Students learn how teams form, develop, and perform."}, {"id": "c95e72b4-5588-4b6f-9842-15f47e4b291e", "type": "subtopic", "title": "Managerial Communication", "children": [{"id": "74307712-075d-4a7e-927b-b7c6dad306ff", "type": "concept", "title": "Active listening"}, {"id": "2daefb30-79c6-4a74-956e-1e216b69595e", "type": "concept", "title": "Feedback and difficult conversations"}, {"id": "e7c64702-b0a1-4911-96e7-f4de4fbfab36", "type": "concept", "title": "Meetings, presentations, and written communication"}], "description": "Students learn communication as a core management tool."}, {"id": "2fda185d-66d2-41ce-9abc-26da5b27d191", "type": "subtopic", "title": "Conflict and Negotiation Basics", "children": [{"id": "8b5e25e3-8628-439d-a7ae-d043b1ffe173", "type": "concept", "title": "Task, relationship, and process conflict"}, {"id": "9f6296c6-e419-4574-aa83-ac31e42a68d4", "type": "concept", "title": "Conflict-handling styles"}, {"id": "cc260465-3095-4cbe-8d17-578b9ade653d", "type": "concept", "title": "Interest-based negotiation"}], "description": "Students learn to diagnose conflict and choose constructive responses."}]}, {"id": "faddd1cd-a13a-4514-8728-40bc6111bc9c", "type": "topic", "title": "Organizational Culture, Diversity, Equity, and Inclusion", "description": "Culture and inclusion shape how people experience work and how organizations perform. This unit links values, norms, identity, and belonging to management practice.", "children": [{"id": "c5eb0cad-cc86-4f50-a841-5d1f213bf1e4", "type": "subtopic", "title": "Organizational Culture", "children": [{"id": "326488d2-dc8e-4b05-b52c-5ea77d5b0454", "type": "concept", "title": "Artifacts, values, assumptions"}, {"id": "b2fe634b-18e7-4cca-b821-4262bca124a5", "type": "concept", "title": "Strong and weak cultures"}, {"id": "66675a96-2166-42ee-b38d-72fe2e0d193c", "type": "concept", "title": "Culture fit and culture add"}], "description": "Students learn how culture guides behavior even when rules are absent."}, {"id": "bd5af14d-310a-4b91-bd11-2e6f20db5d58", "type": "subtopic", "title": "Diversity and Inclusion", "children": [{"id": "2bbe8867-bc37-4888-84aa-710137ef06d2", "type": "concept", "title": "Surface-level and deep-level diversity"}, {"id": "136a8239-bf0a-4ea7-af03-d91195e0093a", "type": "concept", "title": "Inclusion and belonging"}, {"id": "8580fceb-7021-49d4-bfaa-bd4ef51dcadc", "type": "concept", "title": "Bias, microbehaviors, and psychological safety"}], "description": "Students learn why diverse teams require intentional management."}, {"id": "0845255a-90f4-413c-989a-a08636f464e4", "type": "subtopic", "title": "Managing Across Differences", "children": [{"id": "d62b247a-04a2-4088-8a99-e8aafe0d5fde", "type": "concept", "title": "Inclusive meetings and decision processes"}, {"id": "5e9999d1-53a5-4629-9878-5914fc125cb5", "type": "concept", "title": "Cross-cultural awareness"}, {"id": "054f827c-5c17-4422-b776-8df81ee822ae", "type": "concept", "title": "Equity in opportunities and evaluation"}], "description": "Students practice translating awareness into managerial action."}]}, {"id": "7eca71cd-edaf-42f4-bd8d-5d3a8052541a", "type": "topic", "title": "Power, Politics, Ethics, and Corporate Social Responsibility", "description": "Managers make choices that affect people and stakeholders. This unit connects influence, ethical reasoning, and social responsibility.", "children": [{"id": "8c81c9