ess", "children": [{"id": "07cc5dae-76fb-44cf-966d-de9edb096948", "type": "concept", "title": "Feedforward, concurrent, and feedback controls"}, {"id": "b2262c9b-3f1e-4cee-92f9-f7069396f4a2", "type": "concept", "title": "Standards and variance"}, {"id": "f85ffa9c-6d48-4194-9a64-d60d9a79b200", "type": "concept", "title": "Corrective action"}], "description": "Students learn the basic cycle of setting standards, measuring, comparing, and correcting."}, {"id": "62959372-ef0d-474a-b5b4-41575f9f3689", "type": "subtopic", "title": "Performance Measurement", "children": [{"id": "ac746482-6863-488a-a7ea-47179261e866", "type": "concept", "title": "KPIs and dashboards"}, {"id": "53f01e86-7328-4247-82f0-c1ea5d54546a", "type": "concept", "title": "Balanced scorecard"}, {"id": "077d6794-4b67-48cb-bbd1-3d4f70bcd88c", "type": "concept", "title": "Leading and lagging indicators"}], "description": "Students learn how metrics guide behavior and can also distort it."}, {"id": "d5205a5d-eaf5-4717-a7a4-93e106d4698d", "type": "subtopic", "title": "Accountability and Governance", "children": [{"id": "e2291b95-3ece-43ff-b8a9-6d6702315aa7", "type": "concept", "title": "Ownership and role clarity"}, {"id": "b100706e-9a5b-4744-92cc-77d24eadd2ea", "type": "concept", "title": "Internal controls and risk management"}, {"id": "7d798486-b9a1-45c2-9032-93312429741d", "type": "concept", "title": "Learning-oriented versus blame-oriented control"}], "description": "Students connect control to responsibility and learning."}]}, {"id": "1fa4ddd9-5837-4307-b9a7-604ed1a0d445", "type": "topic", "title": "Managing Change, Innovation, and Organizational Learning", "description": "Organizations must adapt while maintaining performance. This unit teaches how managers lead change, support innovation, and build learning systems.", "children": [{"id": "dfb0c1b6-a822-40a6-a8a7-28e02a220553", "type": "subtopic", "title": "Change Models", "children": [{"id": "5ed324fa-3245-4974-a927-033b91c7f730", "type": "concept", 